// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller (potentially malicious EOA) and candidate newOwner
    function testFuzz_property(address caller, address candidate) public {
        // Keep addresses wide-range but disallow zero address for clarity (still wide)
        vm.assume(caller != address(0));
        vm.assume(candidate != address(0));

        // The deployed contract's admin is the test contract's address at deployment time (address(this) in setUp)
        // We simulate a call to setOwner from the fuzzed caller.
        // For the reference implementation, only the original admin (address(this) at setUp) can change owner.
        // So for any caller != admin, the call will NOT change owner (it should revert due to onlyAdmin).

        // Capture owner before the call
        address ownerBefore = c.owner();

        // Try calling setOwner as the fuzzed caller; detect whether it succeeded or reverted
        bool ok;
        vm.prank(caller);
        try c.setOwner(candidate) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, read owner
        address ownerAfter = c.owner();

        // General rule: In the reference contract, only the original admin (the test contract at deployment)
        // can change owner. Therefore for ANY caller that is not the admin, the call must fail or not change owner.
        // We assert that either the call reverted (ok == false) OR the owner did not change.
        // This holds for all inputs on the reference. The mutant removed the onlyAdmin check, so for some
        // fuzzed caller != admin the mutant will allow the change (ok == true AND ownerAfter == candidate),
        // which violates this universal rule.
        assertTrue(caller == address(this) || (!ok || ownerAfter == ownerBefore));
    }
}

