pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the proposed new owner address. The general rule: when the admin calls setOwner(x),
    // the contract's owner() must equal x after the call. The mutant that uses tx.origin will
    // produce owner()==tx.origin, so if tx.origin != x the mutant will differ.
    function testFuzz_property(address proposedOwner) public {
        // keep domain wide; avoid zero-address corner if desired but not necessary
        // Ensure the caller is the admin (deployer). setUp deployed c from this test contract's address,
        // but in Foundry msg.sender in setUp is the test contract itself, and admin was set to that address.
        // Here we must call as that admin. In tests, the contract (this) is not the EOA; use vm.prank to set msg.sender
        // to the original deployer. The deployer in setUp was the test contract's address (address(this)).

        // vm.prank with address(this) will make the next call have msg.sender == address(this) which matches admin
        vm.prank(address(this));
        bool ok;
        try c.setOwner(proposedOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract must accept the call (no revert) and set owner == proposedOwner.
        // We assert the property by reading the public getter owner(). This is a single assertTrue as required.
        // The mutant that assigns owner = tx.origin will fail this assertion for any proposedOwner != tx.origin.
        assertTrue(ok && c.owner() == proposedOwner);
    }
}

