pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an address that will attempt to call setOwner
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses in normal EOA range (non-zero), but wide
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // determine admin and current owner
        address admin = address(this); // in setUp, c was deployed by this contract, so admin == this
        address initialOwner = c.owner();

        // We want to capture the universal property: only admin can call setOwner.
        // Under the reference implementation, any non-admin call to setOwner must revert.
        // Under the mutant, when owner != admin, a caller equal to owner can call setOwner.

        // Ensure the caller is not the admin to test the restriction
        vm.assume(caller != admin);

        // Drive the call as the fuzzed caller and record whether setOwner succeeds
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees that if caller != admin, the call fails (ok == false).
        // The mutant allows success when caller == initialOwner (because it checks owner instead of admin),
        // so for some fuzzed inputs (caller == initialOwner and initialOwner != admin) ok will be true and the mutant breaks.
        assertTrue(!ok);
    }
}

