pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: attacker is a candidate caller, newOwner is the address to set
    function testFuzz_property(address attacker, address newOwner) public {
        // Keep domain wide: avoid zero-address for newOwner to make meaning clear but allow it otherwise
        // We do not overly constrain attacker so fuzzer can find cases where owner != admin
        vm.assume(newOwner != address(0));

        // admin is the deployer in setUp(); obtain it by creating a new contract to read admin cannot be read (private)
        // But we know admin == address(this) at deployment of C in setUp()? No: setUp deployed C from this test contract address.
        // In reference contract, admin was set to msg.sender (the test contract) when setUp created C. So admin == address(this).
        // To exercise the difference we need a scenario where owner != admin. After deployment, owner == admin too.
        // So first have the true admin (this test contract) change owner to some address via setOwner.

        // As the test contract is the deployer/admin, we can call setOwner to set owner to attacker (making owner != admin if attacker != address(this)).
        bool ok;
        try c.setOwner(attacker) {
            ok = true;
        } catch {
            ok = false;
        }
        // This call must succeed in the reference contract because caller is admin (the test contract that deployed C).
        // If it unexpectedly reverts, abort the test case (do not assert false) — keep admissible domain wide.
        if (!ok) return;

        // Now owner() == attacker (in the reference). The invariant we assert is:
        // For any subsequent caller X (we use attacker as the fuzzed caller), only admin (the original deployer) can change owner again.
        // So if a non-admin address (attacker) tries to call setOwner, it must fail in the reference contract.
        // The mutant that compares msg.sender == owner instead of admin will allow attacker (who is owner now) to succeed.

        // Simulate attacker trying to call setOwner to set owner to newOwner
        vm.prank(attacker);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // SINGLE assertion: in the correct contract, a call to setOwner by the current owner (who is not admin) must NOT succeed.
        // We assert that the call by attacker (who we earlier made the owner) did NOT succeed (ok == false) OR attacker == admin.
        // But admin == address(this); attacker is fuzzed — the universal property is: if caller != admin then setOwner must revert.
        // Equivalent single assertTrue reading c's public surface: after the attempted call, c.owner() must equal attacker when the call failed,
        // but must equal newOwner if the call succeeded. To make a single assertion that the reference always satisfies and the mutant breaks,
        // we assert that if attacker != address(this) then c.owner() != newOwner (i.e., non-admin caller cannot change owner).

        if (attacker != address(this)) {
            // After the attempted call, in the reference c.owner() should still be attacker (unchanged), so it must not equal newOwner.
            assertTrue(c.owner() != newOwner);
        } else {
            // If attacker is admin (address(this)), the call is allowed and owner should equal newOwner — in that case we do not assert anything restrictive.
            // To keep a single assertTrue in all executions, use a tautology for this branch: owner() == owner()
            assertTrue(c.owner() == c.owner());
        }
    }
}

