pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // test runner (this contract) deploys C, so msg.sender inside C is address(this)
        // but forge's Test harness sets tx.origin etc; to make the admin a fuzzable actor we
        // capture the deployer as the address that performs setUp() — that's address(this)
        c = new C();
        deployer = address(this);
    }

    // fuzzed parameters: caller tries to invoke setOwner, and newOwner is the target
    function testFuzz_property(address caller, address newOwner) public {
        // Keep inputs wide but avoid the zero address for clarity (still wide domain)
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // RULE to test: only the original deployer (admin) can make setOwner succeed.
        // Arrange: ensure owner != deployer so that mutant (which allows owner as admin)
        // can potentially let a non-deployer succeed. We fuzzed newOwner already; if
        // the current owner equals deployer we change it by a deployer call to a different owner.

        // If current owner is still deployer, perform a legitimate admin call to set owner to some other addr
        if (c.owner() == deployer) {
            // call as deployer (we are deployer here)
            c.setOwner(address(0xdead));
            // ensure owner now differs from deployer to make the domain where mutant can differ
            vm.assume(c.owner() != deployer);
        }

        // Now current owner != deployer. The property: only deployer may successfully call setOwner.
        // Act: have 'caller' attempt to call setOwner(newOwner)
        bool ok;
        // simulate caller by prank; caller may be any EOA (fuzzed)
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Observe: in the correct contract, the call only succeeds (ok==true) when caller == deployer.
        // So the assertion: (ok == (caller == deployer)) must hold for all admissible inputs.
        // This is a single assertion observing c via its public owner() implicitly through the success boolean.
        assertTrue(ok == (caller == deployer));
    }
}

