import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public { c = new C(); admin = address(this); }

    // fuzz the target owner address; the distinguishing behavior is the return value of setOwner
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid zero-address if desired (not necessary): allow any address
        // Call setOwner as the admin (msg.sender == admin). In setUp we deployed c from this contract,
        // so this contract is the admin.
        bool ok;
        try c.setOwner(newOwner) returns (bool ret) {
            // call completed; ret is the returned boolean
            ok = ret;
        } catch {
            // if it reverted, mark as false (but reference should not revert for any newOwner when called by admin)
            ok = false;
        }

        // The universal property: for any newOwner, the correct contract returns true when called by admin.
        // The mutant (which returns false) will cause this assertion to fail for some fuzzed newOwner values.
        assertTrue(ok);
    }
}

